const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const opinia = {
  autor: String(body.autor || 'Klient').slice(0, 100),
  ocena: body.ocena != null && body.ocena !== '' ? Math.max(1, Math.min(5, Number(body.ocena))) : null,
  tresc: String(body.tresc || body.opinia || '').trim().slice(0, 2000),
  reviewName: body.reviewName ? String(body.reviewName) : '', // np. accounts/1/locations/2/reviews/3 (Google)
};
if (!opinia.tresc) throw new Error('Brak treści opinii w payloadzie (pole tresc albo opinia).');
return { json: { opinia_oryginalna: opinia, ...opinia } };

const SYSTEM = "Jesteś asystentem odpowiadającym w imieniu firmy klienta na opinie zostawione przez jej klientów (Google, Allegro lub inna platforma z recenzjami). Twoje zadanie:\n1. Oceń sentyment opinii: pozytywna, neutralna lub negatywna.\n2. Napisz krótką (2-4 zdania), profesjonalną odpowiedź po polsku, dopasowaną tonem do opinii.\n3. Jeśli opinia jest pozytywna - podziękuj konkretnie za to, co klient docenił, nie ogólnikowo.\n4. Jeśli opinia jest negatywna - przeproś, nie usprawiedliwiaj się nadmiernie, zaproponuj kontakt bezpośredni w celu rozwiązania sprawy (adres e-mail z danych firmy). Nie obiecuj konkretnych rekompensat, zniżek ani terminów.\n5. Nigdy nie wymyślaj faktów, nazwisk pracowników, numerów zamówień ani szczegółów, których nie ma w treści opinii.\n6. Nie używaj emoji. Nie podpisuj odpowiedzi wymyślonym imieniem.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"sentyment\": \"pozytywna\" | \"neutralna\" | \"negatywna\", \"odpowiedz\": tekst odpowiedzi}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Dane firmy: ${$('Konfiguracja').first().json.daneFirmy}\n\nOpinia klienta (ocena: ${$json.ocena != null ? $json.ocena + '/5' : 'brak oceny'}):\n${$json.tresc}`;
return {
  json: {
    ...$json,
    _aiRequest: {
      model: ($('Konfiguracja').first().json.modelAI || "gpt-4o-mini"),
      max_tokens: 300,
      temperature: 0.3,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: String(user).slice(0, 12000) },
      ],
    },
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (odpowiedź na opinię)').item.json };
delete ctx._aiRequest;
let out = {};
let aiError = '';
try {
  const raw = $json.choices?.[0]?.message?.content ?? '';
  out = JSON.parse(raw);
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"sentyment":"","odpowiedz":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };

